"""Mutation check for tools/mcp/tests: mutants of godot_mcp.py generated by fixed AST rules (not
picked by hand), each loaded through GODOT_MCP_PATH; a mutant the suite passes on has survived.

Rules, applied inside functions (docstrings left alone): swap a comparison (== !=, < >=, > <=,
in / not in, is / is not), and <-> or, drop a `not`, flip True/False, int n -> n+1, prefix a
non-empty string, replace a statement with `pass` (a `return` with `return None`).

  uv run --with pytest --with 'mcp>=2.3,<3' python -I tools/mcp/tests/mutants.py . <scratch dir>   # ~2.5 min on 16 cores
"""

from __future__ import annotations

import ast
import collections
import copy
import json
import os
import shutil
import subprocess
import sys
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

SWAP = {ast.Eq: ast.NotEq, ast.NotEq: ast.Eq, ast.Lt: ast.GtE, ast.GtE: ast.Lt, ast.Gt: ast.LtE,
        ast.LtE: ast.Gt, ast.In: ast.NotIn, ast.NotIn: ast.In, ast.Is: ast.IsNot, ast.IsNot: ast.Is}
STATEMENTS = (ast.Expr, ast.Assign, ast.AugAssign, ast.If, ast.For, ast.Return)


def sites(tree: ast.Module) -> list[tuple[int, str, object]]:
    """(index of the node in ast.walk order, rule, detail) for every mutation."""
    docstrings = {id(f.body[0].value) for f in ast.walk(tree)
                  if isinstance(f, (ast.FunctionDef, ast.Module)) and f.body
                  and isinstance(f.body[0], ast.Expr) and isinstance(f.body[0].value, ast.Constant)}
    inside = {id(n) for f in ast.walk(tree) if isinstance(f, ast.FunctionDef) for n in ast.walk(f)}
    out = []
    for i, n in enumerate(ast.walk(tree)):
        if id(n) not in inside or id(n) in docstrings:
            continue
        if isinstance(n, ast.Compare):
            out += [(i, "cmp", j) for j, op in enumerate(n.ops) if type(op) in SWAP]
        elif isinstance(n, ast.BoolOp):
            out.append((i, "boolop", None))
        elif isinstance(n, ast.Constant):
            if isinstance(n.value, bool):
                out.append((i, "bool", None))
            elif isinstance(n.value, int):
                out.append((i, "int", None))
            elif isinstance(n.value, str) and n.value:
                out.append((i, "str", None))
        for field, value in ast.iter_fields(n):
            children = value if isinstance(value, list) else [value]
            for j, child in enumerate(children):
                key = (field, j if isinstance(value, list) else None)
                if isinstance(child, ast.UnaryOp) and isinstance(child.op, ast.Not):
                    out.append((i, "not", key))
                if (isinstance(value, list) and isinstance(child, STATEMENTS)
                        and not (isinstance(child, ast.Expr) and id(child.value) in docstrings)):
                    out.append((i, "pass", key))
    return out


def mutate(tree: ast.Module, site: tuple[int, str, object]) -> tuple[str, ast.AST]:
    t = copy.deepcopy(tree)
    i, rule, detail = site
    n = list(ast.walk(t))[i]
    target = n
    if rule == "cmp":
        n.ops[detail] = SWAP[type(n.ops[detail])]()
    elif rule == "boolop":
        n.op = ast.Or() if isinstance(n.op, ast.And) else ast.And()
    elif rule == "bool":
        n.value = not n.value
    elif rule == "int":
        n.value += 1
    elif rule == "str":
        n.value = "MUT:" + n.value
    else:
        field, j = detail
        value = getattr(n, field)
        child = value[j] if j is not None else value
        target = child
        if rule == "not":
            new = child.operand
        else:
            new = ast.Return(value=None) if isinstance(child, ast.Return) else ast.Pass()
        if j is None:
            setattr(n, field, new)
        else:
            value[j] = new
    ast.fix_missing_locations(t)
    return ast.unparse(t), target


def main() -> None:
    repo, out = Path(sys.argv[1]).resolve(), Path(sys.argv[2]).resolve()
    out.mkdir(parents=True, exist_ok=True)
    src = (repo / "tools/mcp/godot_mcp.py").read_text()
    tree = ast.parse(src)
    owner = {id(n): f.name for f in ast.walk(tree) if isinstance(f, ast.FunctionDef) for n in ast.walk(f)}
    originals = list(ast.walk(tree))

    def pytest(module: Path, tag: str, stop_first: bool = True) -> int:
        cmd = [sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider", "--import-mode=importlib",
               f"--basetemp={out}/tmp-{tag}", "tools"] + (["-x"] if stop_first else [])
        env = {**os.environ, "GODOT_MCP_PATH": str(module), "GODOT_BIN": "/nonexistent"}
        try:
            return subprocess.run(cmd, cwd=repo, env=env, capture_output=True, text=True, timeout=600).returncode
        finally:  # each run leaves temp git repos; hundreds of runs exhaust a tmpfs's inodes
            shutil.rmtree(out / f"tmp-{tag}", ignore_errors=True)

    base = out / "base.py"
    base.write_text(ast.unparse(tree))
    assert pytest(base, "base", stop_first=False) == 0, "suite must pass on the unparsed original"

    jobs = []
    for k, site in enumerate(sites(tree)):
        code, _ = mutate(tree, site)
        node = originals[site[0]]
        target = node
        if site[1] in ("not", "pass"):
            field, j = site[2]
            value = getattr(node, field)
            target = value[j] if j is not None else value
        label = {"fn": owner.get(id(target), owner.get(id(node), "?")), "line": getattr(target, "lineno", None),
                 "rule": site[1], "code": (ast.get_source_segment(src, target) or "").splitlines()[0][:100]}
        path = out / f"mutant-{k}.py"
        path.write_text(code)
        jobs.append((k, path, label))

    def run(job):
        k, path, label = job
        return label, pytest(path, str(k))

    with ThreadPoolExecutor(os.cpu_count() or 4) as pool:
        results = list(pool.map(run, jobs))
    odd = [(lab, rc) for lab, rc in results if rc not in (0, 1)]
    assert not odd, odd
    total = collections.Counter(lab["fn"] for lab, _ in results)
    survived = [lab for lab, rc in results if rc == 0]
    lost = collections.Counter(lab["fn"] for lab in survived)
    print(f"mutants {len(results)}, killed {len(results) - len(survived)}, survived {len(survived)}")
    for fn in sorted(total):
        print(f"  {fn:15} {total[fn] - lost[fn]:3}/{total[fn]:3} killed")
    for lab in sorted(survived, key=lambda x: (x["fn"], x["line"] or 0)):
        print(f"SURVIVED {lab['fn']}:{lab['line']} {lab['rule']:6} {lab['code']}")
    (out / "survivors.json").write_text(json.dumps(survived, indent=1))


if __name__ == "__main__":
    main()
